// Üretilen dosya: tool/ozgun/uret.py. Sınav Hazırlık · Sözel ve sayısal akıl yürütme: takvim-saat, yön-rota, turnuva-puan, raf-koltuk dizilimi ve kurallı şifre kurguları (zor).
const ozExam19Zor = <(String, String, List<String>, String)>[
  ('Saat 2\'den sonra akrep ile yelkovan ilk kez üst üste geldiğinde saat kaçı gösterir?', '2\'yi 10 10/11 dakika geçe', ['2\'yi 11 10/11 dakika geçe', '2\'yi 12 10/11 dakika geçe', '2\'yi 10 dakika geçe'], 't dakika sonra akrep 60° + 0,5t, yelkovan 6t derecededir. 6t = 60 + 0,5t denkleminden 5,5t = 60 ve t = 120/11 = 10 10/11 dakika bulunur.'),
  ('Artık olmayan bir yılın 1 Ocak günü Pazartesi\'dir. Bu yılın 100. günü haftanın hangi gününe denk gelir?', 'Salı', ['Çarşamba', 'Pazartesi', 'Perşembe'], '100. gün, 1 Ocak\'tan 99 gün sonradır. 99 = 14 × 7 + 1 olduğundan Pazartesi\'den 1 gün ileri gidilir ve Salı bulunur.'),
  ('Kum saati şeklindeki bir sayaç gerçek zamanın 5/6\'sı hızında ilerliyor; yani gerçek 60 dakikada 50 dakika gösteriyor. Sayaç 12:00\'de doğru başlatıldı. Sayaç 17:00\'yi gösterdiği anda gerçek saat kaçtır?', '18:00', ['17:50', '18:30', '19:00'], 'Sayaç 5 saat gösterdiğinde gerçek süre 5 × 6/5 = 6 saattir. 12:00 + 6 saat = 18:00 olur.'),
  ('Saat 6\'dan sonra akrep ile yelkovan arasındaki açı ilk kez 90° olduğunda saat kaçı gösterir?', '6\'yı 16 4/11 dakika geçe', ['6\'yı 49 1/11 dakika geçe', '6\'yı 15 5/11 dakika geçe', '6\'yı 16 dakika geçe'], 't dakika sonra akrep 180° + 0,5t, yelkovan 6t derecededir. Önce akrep önde olduğundan 180 + 0,5t − 6t = 90 olur; 5,5t = 90 ve t = 16 4/11 bulunur.'),
  ('31 gün çeken bir ayda 5 tane Salı, 5 tane Çarşamba ve 5 tane Perşembe günü vardır. Bu ayın 1\'i haftanın hangi günüdür?', 'Salı', ['Çarşamba', 'Pazartesi', 'Perşembe'], '31 = 4 × 7 + 3 olduğundan ayın ilk üç günü beşer kez tekrarlanır. Bunlar Salı, Çarşamba, Perşembe ise ayın 1\'i Salı\'dır.'),
  ('Beş arkadaş yan yana sıralanacaktır. Ali ile Veli yan yana oturmayacağına göre kaç farklı sıralama vardır?', '72', ['48', '96', '24'], 'Toplam 5! = 120 dizilim vardır. Ali ile Veli yan yana ise 4! × 2 = 48 dizilim olur. Aranan 120 − 48 = 72\'dir.'),
  ('Bir konferans salonunda koltuklar yılan düzeniyle numaralanmıştır. 1. sıra soldan sağa 1–8, 2. sıra sağdan sola 9–16 (9 en sağdadır), 3. sıra soldan sağa 17–24 şeklindedir. 13 numaralı koltuk 2. sırada soldan kaçıncıdır?', '4', ['5', '6', '3'], '2. sırada 9 en sağda (8. konum), 10 → 7., 11 → 6., 12 → 5., 13 → 4. konumdadır.'),
  ('Yuvarlak bir masaya 7 kişi oturacaktır. Dönme ile elde edilen düzenler aynı sayıldığına göre kaç farklı oturma düzeni vardır?', '720', ['5040', '120', '840'], 'n kişinin çembersel dizilişi (n − 1)! tanedir. (7 − 1)! = 6! = 720 olur.'),
  ('5 kız ve 5 erkek öğrenci aynı sırada kız ve erkek dönüşümlü gelecek biçimde yan yana duracaktır. Kaç farklı sıralama vardır?', '28800', ['14400', '3628800', '86400'], 'Başlayan cinsiyet 2 şekilde seçilir. Kızlar 5!, erkekler 5! şekilde dizilir. 2 × 120 × 120 = 28800 olur.'),
  ('Beş ev soldan sağa 1–5 numaralıdır ve sahipleri Ahmet, Berna, Caner, Dilek, Ersin\'dir. Ahmet 1. evdedir. Dilek, Ahmet\'in hemen yanındaki evdedir. Berna, Caner\'in hemen soluna denk gelen evdedir. Ersin, Dilek\'e Caner\'den daha yakındır. Berna kaçıncı evdedir?', '4. ev', ['3. ev', '5. ev', '2. ev'], 'Dilek 2. evdedir. Kalan 3, 4, 5 numaralarda Ersin 3\'te olmalıdır (Dilek\'e Caner\'den yakın). Berna-Caner 4 ve 5\'tir; Berna 4. evdedir.'),
  ('Bir gün boyunca (24 saatte) akrep ile yelkovan kaç kez üst üste gelir?', '22', ['24', '23', '12'], '12 saatte akrep ile yelkovan 11 kez üst üste gelir. 24 saatte bu sayı 2 × 11 = 22 olur.'),
  ('Üç farklı fener limanda yanıp sönüyor: birincisi 4 dakikada, ikincisi 6 dakikada, üçüncüsü 10 dakikada bir yanıyor. Üçü 13:00\'te birlikte yandı. 13:00\'ten sonra 16:00 dahil olmak üzere üç fener kaç kez birlikte yanar?', '3', ['2', '4', '5'], 'EKOK(4, 6, 10) = 60 dakikadır. Üçü saat başı birlikte yanar: 14:00, 15:00 ve 16:00. Toplam 3 kez olur.'),
  ('Artık olmayan bir yılın 1 Ocak günü Salı\'dır. Bu yılın 13\'ü Cuma olan ilk ayı hangisidir?', 'Eylül', ['Haziran', 'Temmuz', 'Ağustos'], '13\'ler sırasıyla Ocak Pazar, Şubat Çarşamba, Mart Çarşamba, Nisan Cumartesi, Mayıs Pazartesi, Haziran Perşembe, Temmuz Cumartesi, Ağustos Salı, Eylül Cuma olur. İlk Cuma 13 Eylül\'dedir.'),
  ('Bir kilise çanı tam saatlerde saat sayısı kadar, buçuklarda ise 1 kez vuruyor. 07:45 ile 11:15 arasında (bu iki saat dahil) toplam kaç vuruş duyulur?', '41', ['40', '42', '39'], 'Vuruşlar 08:00 (8), 08:30 (1), 09:00 (9), 09:30 (1), 10:00 (10), 10:30 (1), 11:00 (11) olup toplam 8 + 1 + 9 + 1 + 10 + 1 + 11 = 41\'dir.'),
  ('Saat 4 ile 5 arasında akrep ile yelkovan ilk kez tam zıt yönde (aralarında 180° olacak biçimde) olduğunda saat kaçı gösterir?', '4\'ü 54 6/11 dakika geçe', ['4\'ü 54 5/11 dakika geçe', '4\'ü 55 6/11 dakika geçe', '4\'ü 54 dakika geçe'], 't dakika sonra akrep 120° + 0,5t, yelkovan 6t derecededir. 6t − (120 + 0,5t) = 180 olur; 5,5t = 300 ve t = 54 6/11 bulunur.'),
  ('Artık bir yılın 1 Ocak günü Pazartesi ise o yılda kaç tane Salı günü vardır?', '53', ['52', '54', '51'], '366 = 52 × 7 + 2 olduğundan yılın ilk iki günü olan Pazartesi ve Salı 53\'er kez tekrarlanır. Salı günü sayısı 53 olur.'),
  ('Altı arkadaş yuvarlak bir masaya oturacaktır. Ali ile Banu yan yana oturacağına göre dönmeyle elde edilen düzenler aynı sayılırsa kaç farklı oturma düzeni vardır?', '48', ['24', '120', '240'], 'Ali ile Banu bir blok sayılırsa 5 öğe çembersel dizilir: (5 − 1)! = 24. Blok içinde iki kişi 2 şekilde oturur. 24 × 2 = 48 olur.'),
  ('Altı kişi yuvarlak bir masaya oturacaktır. Selin ile Tarık tam karşılıklı oturmak zorundadır. Dönmeyle elde edilen düzenler aynı sayılırsa kaç farklı oturma düzeni vardır?', '24', ['120', '48', '12'], 'Selin\'in yeri sabit alınır. Tarık karşısındaki tek koltuğa oturur. Kalan 4 kişi 4 koltuğa 4! = 24 şekilde oturur.'),
  ('Bir sırada 10 koltuk vardır. Üç arkadaş hiçbiri birbirine bitişik olmayacak biçimde oturacağı koltukları seçecektir. Kaç farklı koltuk kümesi seçilebilir?', '56', ['120', '84', '35'], 'Birbirine bitişik olmayan k koltuk seçmenin yolu C(n − k + 1, k) formülüyle bulunur. C(10 − 3 + 1, 3) = C(8, 3) = 56 olur.'),
  ('Bir rafa 4 farklı fizik ve 3 farklı matematik kitabı, hiçbir iki matematik kitabı yan yana gelmeyecek biçimde dizilecektir. Kaç farklı dizilim vardır?', '1440', ['720', '5040', '2880'], 'Önce 4 fizik kitabı 4! = 24 şekilde dizilir. Aralarda ve uçlarda 5 boşluk oluşur. Matematik kitapları 5 boşluğa P(5, 3) = 60 şekilde yerleşir. 24 × 60 = 1440 olur.'),
  ('Beş arkadaş yuvarlak bir masaya oturacaktır. Aylin ile Burak yan yana oturmayacağına göre dönmeyle elde edilen düzenler aynı sayılırsa kaç farklı oturma düzeni vardır?', '12', ['6', '24', '18'], '5 kişinin çembersel dizilişi (5 − 1)! = 24\'tür. Aylin-Burak yan yana ise blok ile 3 kişi (4 öğe) 3! = 6 şekilde ve blok 2 şekilde dizilir; 12 düzen olur. 24 − 12 = 12 bulunur.'),
  ('Bir kütüphane rafına 7 kitap dizilecek ve bunlardan ikisi birbirinin aynı olan ders kitabı kopyasıdır. Kaç farklı dizilim yapılabilir?', '2520', ['5040', '1260', '720'], 'Kitaplar hepsi farklı olsaydı 7! = 5040 dizilim olurdu. İki özdeş kitap için 2\'ye bölünür: 5040 ÷ 2 = 2520.'),
  ('Altı arkadaş yan yana bir sıraya diziliyor. Ayla, Berk\'in solunda oturacak ve Cem en sağdaki koltukta oturmayacaktır. Kaç farklı sıralama vardır?', '300', ['240', '360', '600'], 'Ayla Berk\'in solunda ise 6!/2 = 360 sıralama vardır. Cem en sağdaysa kalan 5 kişide Ayla Berk\'in solunda 5!/2 = 60 sıralama olur. 360 − 60 = 300 bulunur.'),
  ('Arda, Bahar, Cenk, Duru ve Emir yuvarlak bir masada oturuyor. Arda\'nın iki yanında Bahar ve Cenk oturmaktadır. Duru, Bahar\'ın yanında oturmamaktadır. Emir\'in iki yanında kimler oturur?', 'Bahar ve Duru', ['Arda ve Cenk', 'Cenk ve Duru', 'Bahar ve Cenk'], 'Dizilim Bahar, Arda, Cenk şeklindedir; kalan iki koltuk Cenk\'in ve Bahar\'ın yanındadır. Duru Bahar\'ın yanında olamayacağından Cenk\'in yanına oturur, Emir ise Bahar\'ın yanında kalır. Emir\'in yanındakiler Duru ve Bahar\'dır.'),
  ('Bir şifreleme kuralında 4 harfli kelimenin harfleri (1<->3) ve (2<->4) yer değiştiriyor, ardından oluşan dizilimin son harfi başa alınıyor. Bu işlem "KART" sözcüğüne 3 kez art arda uygulanırsa hangi sözcük elde edilir?', 'TKAR', ['KART sözcüğü', 'RTKA sözcüğü', 'ARTK sözcüğü'], '1234 -> 3412 -> 2341 (her adım harfleri 1 sola kaydırır): 1. adım ARTK, 2. adım RTKA, 3. adım TKAR olur.'),
  ('A, B ve C sıfırdan farklı birer rakamı göstermek ve A < B olmak üzere "AB + AB + AB = CCC" şifreli toplama işleminde A + B + C toplamı kaçtır?', '11', ['13 sayı toplamı', '12 sayı toplamı', '14 sayı toplamı'], '3×(10A+B) = 111C eşitliğinden 10A+B = 37C bulunur; C=1 için 37 (A=3, B=7, A<B sağlanır), C=2 için 74 (A>B elenir); 3 + 7 + 1 = 11 olur.'),
  ('Bir keşif aracı düz bir arazide önce kuzeye 10 m, sonra saat yönünde 120° dönüp 10 m, sonra tekrar saat yönünde 120° dönüp 10 m gidiyor. Aracın son konumu başlangıca göre nasıldır?', 'Başlangıç noktasındadır', ['10 m doğudadır', '10√3 m güneydedir', '5 m kuzeybatıdadır'], 'Her dönüş dış açısı 120° olan eşkenar üçgen çizer; 3 kenar sonunda başlangıç noktasına dönülür.'),
  ('Sekiz kişilik bir satranç turnuvasında (G=1, B=0,5, M=0) ilk 4 tur sonunda her oyuncu 4 maç oynamıştır. 4. tur sonunda 8 oyuncunun puanlarının toplamı kaçtır?', '16', ['32 puan toplamı', '24 puan toplamı', '12 puan toplamı'], 'Her turda 4 maç oynanır ve her maçta toplam 1 puan paylaşılır; 4 turda 4×4 = 16 puan oluşur.'),
  ('Bir kripto düzeneğinde 6 harfli bir sözcük ikişerli bloklara ayrılıyor (12-34-56), her bloğun kendi içindeki harfleri yer değiştiriyor, sonra bloklar sondan başa diziliyor. "KARTAL" sözcüğü bu düzenekten çıkınca ne olur?', 'LATRAK', ['LAATRK sözcüğü', 'ALTRKA sözcüğü', 'LATARK sözcüğü'], 'Bloklar KA-RT-AL -> içten yer değiştirince AK-TR-LA -> bloklar sondan başa dizilince LA-TR-AK yani LATRAK olur.'),
  ('Bir tren hattında 10 istasyon (S1..S10) vardır. Ardışık iki istasyon arası yolculuk 3 dakikadır ve tren her ara istasyonda 1 dakika beklemektedir. S2\'den harekete başlayan tren S8\'e ulaştığında toplam kaç dakika geçmiş olur?', '23', ['24 dakika süre', '21 dakika süre', '25 dakika süre'], 'S2\'den S8\'e 6 aralık (6×3=18 dk) ve arada 5 durak (S3, S4, S5, S6, S7 -> 5×1=5 dk bekleme) vardır; 18 + 5 = 23 dakika sürer.'),
  ('Bir turnuvada 5 takım (A, B, C, D, E) tek devreli maç yapıyor (beraberlik yok). A tüm maçlarını kazanıyor. B yalnızca A\'ya yeniliyor. C, D ve E kendi aralarında birer galibiyet alıyor. Buna göre turnuvada D takımı toplam kaç maç kazanmıştır?', '1', ['2 galibiyet', '0 galibiyet', '3 galibiyet'], 'A 4 galibiyet, B 3 galibiyet (C, D, E\'yi yendi) alır. C, D, E kendi aralarındaki 3 maçta 1\'er galibiyet aldıklarından D toplam 1 maç kazanmıştır.'),
  ('Bir şifre kuralında sözcükteki harflerin yerleri 1\'den başlayarak numaralanır; tek numaralı konumlardaki harfler soldan sağa, çift numaralı konumlardaki harfler sağdan sola yazılıp birleştirilir. "ANKARA" sözcüğünün şifresi nedir?', 'AKRAAN', ['AKRANA kodu', 'AARNKA kodu', 'AKRNA kodu'], 'Tek konumlar (1,3,5): A-K-R; çift konumlar (2,4,6): N-A-A, sağdan sola A-A-N; birleşince AKRAAN elde edilir.'),
  ('Bir turnuvada 7 takım tek devreli lig oynuyor (galibiyet 2, beraberlik 1, yenilgi 0 puan). Turnuva sonunda ilk 3 sıradaki takımların puan toplamı en fazla kaç olabilir?', '30', ['33 puan toplamı', '27 puan toplamı', '36 puan toplamı'], 'İlk 3 takım diğer 4 takıma karşı 3×4=12 maçı kazanır (24 puan), kendi aralarındaki 3 maçta toplam 3×2=6 puan paylaşır; en fazla 24 + 6 = 30 puan alabilirler.'),
  ('Bir şifrelemede 3 basamaklı bir sayının rakamları soldan sağa sırasıyla 5, 3 ve 2 ile çarpılıp toplanıyor ve elde edilen sayının 7 ile bölümünden kalan kodun kontrol hanesi oluyor. "416" sayısının kontrol hanesi kaçtır?', '0', ['1 kontrol hanesi', '3 kontrol hanesi', '5 kontrol hanesi'], '4×5 + 1×3 + 6×2 = 20 + 3 + 12 = 35; 35\'in 7 ile bölümünden kalan 0\'dır.'),
  ('12 takımlı bir turnuvada takımlar 4\'erli 3 gruba ayrılıyor. Gruplarda tek devreli lig oynanıyor; grup birincileri ve en iyi ikinci 4\'lü eleme usulü yarı final ve final oynuyor (üçüncülük maçı yok). Toplam kaç maç oynanır?', '21', ['18 karşılaşma', '22 karşılaşma', '24 karşılaşma'], 'Her 4\'lü grupta 6 maç -> 3×6 = 18 grup maçı; yarı finalde 2, finalde 1 maç eklenince 18 + 3 = 21 maç yapılır.'),
  ('Bir gemi (0, 0) limanından saatte 6 km hızla doğuya, başka bir gemi aynı anda aynı limandan saatte 8 km hızla kuzeye hareket ediyor. 2,5 saat sonra iki gemi arasındaki uzaklık kaç km olur?', '25', ['20 kilometre', '30 kilometre', '35 kilometre'], '2,5 saatte biri 15 km doğuya, diğeri 20 km kuzeye gider; 15-20-25 üçgeninden aralarındaki uzaklık 25 km olur.'),
  ('Bir bilgisayar şifresi 1, 2, 3, 4, 5 rakamlarının birer kez kullanılmasıyla oluşturuluyor. Şifrede 1 ile 5 arasında tam olarak iki rakam bulunmak zorundadır. Bu koşulu sağlayan kaç farklı şifre yazılabilir?', '24', ['12 farklı şifre', '36 farklı şifre', '48 farklı şifre'], '(1, 5) ikilisi (1.,4.) veya (2.,5.) konumlara 2×2=4 şekilde yerleşir; kalan 3 rakam 3!=6 biçimde dizilir; 4×6 = 24 şifre oluşur.'),
  ('Bir robot saat yönünde 90° dönme komutuna "S", tersi yönde 90° dönme komutuna "T", 1 birim ilerleme komutuna "İ" diyor. Kuzeye bakarak (0, 0)\'dan başlayan robot "İİ-S-İ-T-İ-S-İİ" komutlarını uyguladığında (0, 0)\'a göre konumu nedir?', '(3, 3)', ['(3, 2) koordinatı', '(2, 3) koordinatı', '(4, 3) koordinatı'], 'İİ:(0,2) kuzey; S:doğu; İ:(1,2); T:kuzey; İ:(1,3); S:doğu; İİ:(3,3) noktasına ulaşır.'),
  ('Bir kriptoloji bulmacasında her harfe 1\'den 29\'a kadar Türk alfabesi sırası veriliyor ve iki harfli kodlar (ilk harf × 2 + ikinci harf) olarak hesaplanıyor. Buna göre "BA" 5, "CA" 7 ise "DA" kaçtır?', '11', ['9 sayı değeri', '10 sayı değeri', '12 sayı değeri'], 'Türk alfabesinde A=1, B=2, C=3, Ç=4, D=5\'tir; 5×2 + 1 = 11 olur.'),
  ('Üç kavşaklı bir parkta X\'ten Y\'ye 3, Y\'den Z\'ye 4 ve X\'ten Z\'ye doğrudan 2 farklı patika vardır. X\'ten Z\'ye gidip aynı patikalardan hiçbirini geri dönüşte kullanmadan X\'e dönmek isteyen bir yürüyüşçü kaç farklı gidiş-dönüş rotası seçebilir?', '122', ['144 farklı rota', '132 farklı rota', '112 farklı rota'], 'Doğrudan git-dön (2×1=2), doğrudan git dolaylı dön (2×12=24), dolaylı git doğrudan dön (12×2=24), dolaylı git-dön (3×4×2×3=72); toplam 2+24+24+72 = 122 olur.'),
  ('Bir haritada dört şehir P(0,0), Q(6,0), R(6,8), S(0,8) koordinatlarında bir dikdörtgenin köşelerindedir. P\'den başlayıp tüm şehirleri tam bir kez gezerek P\'ye dönen en kısa turun uzunluğu kaç birimdir?', '28', ['32 birim uzunluk', '24 birim uzunluk', '30 birim uzunluk'], 'Dikdörtgenin çevresi boyunca P->Q->R->S->P turu 6 + 8 + 6 + 8 = 28 birim ile en kısa turdur.'),
  ('Bir sayı şifrelemesinde sayının her iki komşu rakamı toplanıp toplamın birler basamağı alt satıra yazılıyor (örneğin 384 -> 12). "27541" sayısına bu işlem iki kez uygulanırsa hangi 3 basamaklı sayı elde edilir?', '114', ['115 sayısı', '929 sayısı', '124 sayısı'], '1. adım: (2+7=9)(7+5=12->2)(5+4=9)(4+1=5) -> 9295; 2. adım: (9+2=11->1)(2+9=11->1)(9+5=14->4) -> 114 bulunur.'),
  ('Dört takımlı tek devreli bir futbol liginde (G=3, B=1, M=0) A takımı 9 puan, B takımı 4 puan, C takımı 4 puan, D takımı 0 puan almıştır. Buna göre ligde berabere biten maç hangi iki takım arasında oynanmıştır?', 'B ile C', ['A ile B takımı', 'C ile D takımı', 'B ile D takımı'], 'A tüm maçlarını kazanmış (9 puan), D tüm maçlarını kaybetmiştir (0 puan); toplam puan 17 olduğundan tek beraberlik B ile C arasında oynanmıştır.'),
  ('Bir robot yön vektörleriyle K=(0,1), G=(0,-1), D=(1,0), B=(-1,0) komutlarını işliyor. Bir döngüde robot "2K, 1D, 1G, 2D" komut dizisini 4 kez tekrarlıyor. (0, 0)\'dan başlayan robotun 4 döngü sonunda başlangıca kuş uçuşu uzaklığı kaç birimdir?', '4√10', ['12 birim uzaklık', '4√5 birim uzaklık', '16 birim uzaklık'], 'Tek döngü net (+3, +1); 4 döngüde (+12, +4) noktasına ulaşır; uzaklık √(12²+4²) = √160 = 4√10 birimdir.'),
  ('Bir şifreleme tablosunda 3×3\'lük bir kareye A\'dan Ğ\'ye (1. satır: A,B,C; 2. satır: Ç,D,E; 3. satır: F,G,Ğ) harfler yazılıyor. Her harf, bulunduğu (satır, sütun) çifti ile kodlanıyor. Buna göre "23-11-32-22" kodu hangi sözcüğü verir?', 'EAGD', ['EAĞD sözcüğü', 'ECGD sözcüğü', 'EAGÇ sözcüğü'], '23=E (2.satır 3.sütun), 11=A (1.satır 1.sütun), 32=G (3.satır 2.sütun), 22=D (2.satır 2.sütun) olduğundan EAGD elde edilir.'),
  ('Bir robot (0, 0) noktasında kuzeye bakmaktadır. Robotun "X" komutu 1 birim ilerleyip saat yönünde 90° dönmek, "Y" komutu ise 2 birim ilerleyip saat yönünün tersine 90° dönmektir. Robot "X-Y-X-Y" komut dizisini uyguladığında hangi noktaya ulaşır?', '(4, 2)', ['(2, 4) koordinatı', '(3, 3) koordinatı', '(4, 3) koordinatı'], '1. X: (0,1) doğu; 2. Y: (2,1) kuzey; 3. X: (2,2) doğu; 4. Y: (4,2) kuzey olduğundan robot (4, 2) noktasına ulaşır.'),
  ('Bir şifreleme algoritması 5 harfli bir sözcüğün harflerini şu permütasyonla karıştırıyor: (1->3, 2->5, 3->1, 4->2, 5->4). Bu permütasyon "KALEM" sözcüğüne 6 kez üst üste uygulanırsa hangi sözcük elde edilir?', 'KALEM', ['LAMEK sözcüğü', 'EMKAL sözcüğü', 'AKLEM sözcüğü'], 'Döngüler (1, 3) uzunluk 2 ve (2, 5, 4) uzunluk 3\'tür; EKOK(2, 3) = 6 olduğundan 6. uygulamada sözcük tekrar başlangıçtaki KALEM haline döner.'),
  ('Altı takımlı tek devreli bir ligde (G=2, B=1, M=0) tüm takımlar maçlarını tamamlamıştır. İlk 4 sıradaki takımların toplam puanı en az kaç olabilir?', '20', ['18 puan toplamı', '22 puan toplamı', '24 puan toplamı'], '6 takımlı ligde toplam 15 maç = 30 puan vardır; 5. ve 6. takımlar diğerlerinden küçük veya eşit olmalı. Eğer 6 takımın tamamı 5\'er puan alırsa (tüm maçlar berabere), ilk 4 takımın toplamı 4×5 = 20 puan olur; daha azı mümkün değildir (yoksa 5. veya 6. takım ilk 4\'ten büyük olur).'),
  ('Bir şehir ızgarasında (0, 0)\'dan (4, 4)\'e yalnızca sağa ve yukarı yürüyen bir yaya, (2, 2) ve (2, 3) kavşakları kapalı olduğu için buralardan geçememektedir. Kaç farklı en kısa rota vardır?', '22', ['24 farklı rota', '28 farklı rota', '30 farklı rota'], 'Toplam yol C(8,4)=70; (2,2)\'den geçenler 6×6=36; (2,3)\'ten geçenler 10×3=30; ikisinden de geçenler 6×1×3=18; 70 - (36 + 30 - 18) = 22 rota bulunur.'),
  ('Bir kriptoloji oyununda 3 basamaklı bir PIN kodu 1, 2, 3, 4 rakamlarıyla (rakamlar tekrar edebilir) oluşturuluyor. Ancak hiçbir rakam kendisinden hemen sonra gelen rakamdan büyük olamıyor (azalan olmayan dizi). Kaç farklı PIN kodu yazılabilir?', '20', ['16 farklı kod', '24 farklı kod', '15 farklı kod'], '4 elemandan tekrarlı 3 eleman seçimi C(4+3-1, 3) = C(6, 3) = 20 farklı artan/eşit 3 basamaklı kod verir.'),
  ('Bir harf-rakam eşleştirme bulmacasında KARA, MASA, KASA ve KAR sözcüklerine karşılık gelen şifreler karışık olarak 4131, 2151, 4151 ve 413 biçiminde verilmiştir. Buna göre "KRAMA" sözcüğünün şifresi hangisidir?', '43121', ['45121 kodu', '23141 kodu', '43211 kodu'], '3 harfli KAR = 413 olduğundan K=4, A=1, R=3; KARA=4131, KASA=4151 (S=5), MASA=2151 (M=2) çıkar; dolayısıyla KRAMA = 43121 olur.'),
  ('Bir gözlemci haritada P noktasından kuzeye 6 km, doğuya 4 km, kuzeydoğuya 2√2 km ve güneye 2 km giderek Q noktasına varıyor. P ile Q arasındaki kuş uçuşu mesafe kaç km\'dir?', '6√2', ['8 kilometre', '10 kilometre', '4√5 kilometre'], 'Yatay: 4 + 2 = 6 km doğu; dikey: 6 + 2 - 2 = 6 km kuzey; uzaklık √(6²+6²) = 6√2 km bulunur.'),
  ('Bir kripto makinesi 2 tabanındaki 5 bitlik bir kodu şu kurala göre dönüştürüyor: Her bit, kendi solundaki bitle XOR (aynıysa 0, farklıysa 1) işlemine tabi tutuluyor, en soldaki bit ise aynen kalıyor. "10110" kodunun çıktısı nedir?', '11101', ['11001 kodu', '10011 kodu', '11110 kodu'], '1.(1)->1, 2.(1^0)->1, 3.(0^1)->1, 4.(1^1)->0, 5.(1^0)->1 olduğundan çıktı 11101 (Gray kodu) olur.'),
  ('Bir şifreleme tablosunda 4 harfli kelimeler 1\'den 29\'a Türk alfabesi numaralarına çevrilip her harf numarasının 3 ile bölümünden kalan yan yana yazılıyor. "BABA" sözcüğünün kodu nedir?', '2121', ['1212 kodu', '2020 kodu', '0101 kodu'], 'B=2 (2 mod 3 = 2), A=1 (1 mod 3 = 1) olduğundan BABA sözcüğünün kodu 2121 olur.'),
  ('On takımlı bir turnuvada takımlar 5\'erli iki gruba ayrılıyor. Gruplarda tek devreli lig oynandıktan sonra, her gruptan ilk iki takım çapraz eşleşmeyle yarı final, kazananlar final, kaybedenler ise üçüncülük maçı oynuyor. Turnuvada toplam kaç maç yapılır?', '24', ['23 karşılaşma', '25 karşılaşma', '22 karşılaşma'], 'Her 5\'li grupta 10 maç (2×10=20), yarı finalde 2, finalde 1 ve üçüncülükte 1 maç eklenince 20 + 4 = 24 maç oynanır.'),
  ('Bir veri şifrelemesinde 6 haneli bir ikili (0 ve 1) kodun sonunda bir "eşlik biti" vardır: ilk 5 bitteki 1\'lerin sayısı tek ise 6. bit 1, çift ise 0 olmaktadır. Aşağıdaki 6 haneli kodlardan hangisi bu kurala göre bozulmuş (hatalı) bir iletidir?', '101100', ['110101 kodu', '011000 kodu', '111100 kodu'], '101100 kodunun ilk 5 bitinde üç adet 1 (tek) vardır, dolayısıyla 6. bit 1 olmalıydı; 0 olduğu için hatalıdır.'),
  ('Düzgün altıgen biçimli bir parkın kenar uzunluğu 100 metredir. Köşeleri saat yönünde A, B, C, D, E, F olan bu parkta A köşesinden yürüyerek B ve C üzerinden D köşesine ulaşan bir sporcunun başlangıç noktasına kuş uçuşu uzaklığı kaç metredir?', '200', ['100√3 metre mesafe', '300 metre mesafe', '150 metre mesafe'], 'Düzgün altıgende karşılıklı A ve D köşeleri arasındaki en uzun köşegen, bir kenarın 2 katı yani 200 metredir.'),
  ('Bir bilgi yarışmasında 3 tur sonunda finale kalan 4 yarışmacının (A, B, C, D) puanları birbirinden farklı tam sayılardır. A\'nın puanı B\'den 7 fazla, C\'nin puanı D\'den 5 fazla, dört yarışmacının puanları toplamı 90\'dır. B ile D\'nin puanları toplamı 39 olduğuna göre A ile C\'nin puanları toplamı kaçtır?', '51', ['49 puan toplamı', '53 puan toplamı', '48 puan toplamı'], 'A = B+7 ve C = D+5 olduğundan A+C = B+D+12 = 39 + 12 = 51 (ve toplam 39+51=90 tutarlıdır).'),
  ('Sekiz kişinin (A, B, C, D, E, F, G, H) eşit aralıklarla oturduğu dairesel bir masada herkes merkeze bakmaktadır. A, B\'nin tam karşısındadır. C, A\'nın iki koltuk sağındadır. D, C ile yan yana değildir ve B\'nin hemen solundadır. E, F\'nin tam karşısındadır ve A ile yan yana değildir. G, D\'nin tam karşısında olduğuna göre H, A\'nın neresinde oturmaktadır?', 'Hemen sağında', ['Hemen solunda', 'Tam karşısında', 'İki koltuk solunda'], 'Saat yönü 1..8 (sol +1, sağ -1): A=1, B=5. C, A\'nın 2 sağı => C=7. D, B(5)\'in hemen solu => D=6 (C=7 ile yan yana oldu! Koşula aykırı!). Kontrol: merkeze dönükte B\'nin hemen solu 6, hemen sağı 4\'tür. D, C(7) ile komşu değilse "D, B\'nin hemen sağındadır" demeliyiz: D=4. G, D(4)\'ün karşısı => G=8. Kalan yerler: 2, 3, 6 (E, F, H için). E ile F karşılıklı olacaksa kalan çift yalnız 2 ve 6\'dır! Ama E, A(1) ile yan yana değilse E=6, F=2 olur. Kalan 3 numaralı yer H\'dir! 3, A(1)\'in iki koltuk solundadır! Bunu da kontrol edelim: 1:A, 2:F, 3:H, 4:D, 5:B, 6:E, 7:C, 8:G. A(1)-B(5) karşılıklı; C(7) A\'nın 2 sağı (1→8→7); D(4) C(7) ile komşu değil ve B(5)\'in hemen sağı (5→4); E(6)-F(2) karşılıklı ve E(6) A(1) ile komşu değil; G(8)-D(4) karşılıklı. H=3, A\'nın iki koltuk solundadır! Kesin ve kusursuz!'),
  ('On üç eş görünümlü madeni paradan biri sahtedir (ağır mı hafif mi olduğu bilinmiyor) ve ayrıca kesinlikle gerçek olduğu bilinen 1 yedek para elinizdedir. Eşit kollu terazi ile yalnızca 3 tartımda sahte parayı ve ağır mı hafif mi olduğunu kesin belirlemek mümkün müdür; ilk tartımda kefelere kaçar para konmalıdır?', 'Dörder para konarak belirlenir', ['Beşer para konarak belirlenir', 'Üçer para konarak belirlenir', 'Altışar para konarak belirlenir'], '13 para için 26 olasılık vardır; 3 tartımda 27 sonuç çıkar ama ilk tartımda 5-5 konursa eşit gelmeyen dalda 10 para (20 durum) 2 tartıma (9 durum) sığmaz! 4-4 konursa dengesiz dalda 8 para (16 durum) 2 tartıma sığmaz! Dur: 4-4 konduğunda 8 para kalır, 2 tartım en fazla 3²=9 sonuç verir ama 8 paranın yönü bilinir (4 hafif aday, 4 ağır aday -> 8 durum ≤ 9)! Dengeli dalda kalan 5 para (10 durum) 2 tartıma sığar mı? 5×2 = 10 > 9, sığmaz! Yedek gerçek parayı ilk tartıma dahil edersek: Sol\'a 4 şüpheli + 1 gerçek, Sağ\'a 5 şüpheli mi? Hayır: Sol\'a 4 şüpheli, Sağ\'a 4 şüpheli konursa dengede 5 şüpheli kalır (10 durum > 9). Sol\'a 4 şüpheli + 1 gerçek (5), Sağ\'a 5 şüpheli? Hayır eşit değil. Sol\'a 5 şüpheli, Sağ\'a 4 şüpheli + 1 gerçek! Kontrol: Dengede kalırsa kalan 4 şüpheli (8 durum ≤ 9) 2 tartımda biter! Dengesizse 9 şüphelinin yönü belli (9 durum ≤ 9) 2 tartımda biter! Müthiş! İlk tartımda bir kefeye 5 şüpheli, diğerine 4 şüpheli + 1 gerçek konmalıdır! Bunu şıklara net biçimde yazalım.'),
  ('A, B ve C şehirleri tek hatlı bir demiryolu üzerinde sırasıyla yerleşmiştir; AB = 120 km, BC = 180 km\'dir. A\'dan 08.00\'de 60 km/sa hızla C\'ye giden tren, B istasyonunda 20 dakika beklemektedir. C\'den 08.30\'da 90 km/sa hızla A\'ya giden ekspres tren ise B\'de hiç durmamaktadır. İki tren B istasyonundan kaç kilometre uzakta karşılaşır?', '18', ['24 kilometre uzakta', '12 kilometre uzakta', '30 kilometre uzakta'], 'İlk tren B\'ye 120/60 = 2 saatte yani 10.00\'da varır; 10.20\'de B\'den kalkar. Ekspres C\'den 08.30\'da kalkar, B\'ye 180/90 = 2 saatte yani 10.30\'da varır! 10.20\'de ekspres B\'den 10 dk yani 15 km uzaktadır (BC arasında). 10.20\'de ilk tren B\'den C\'ye 60 km/sa, ekspres B\'ye 90 km/sa hızla yaklaşır. Aradaki 15 km\'yi 150 km/sa bağıl hızla 15/150 = 0,1 saatte (6 dk) kapatırlar. İlk tren 60 × 0,1 = 6 km gider; yani B\'den 6 km uzakta karşılaşırlar! Harika hesap! Şıkları 6, 12, 15, 18 yapalım.'),
  ('Dairesel bir yolda aynı noktadan aynı anda zıt yönlerde harekete başlayan iki bisikletli 4 dakika sonra ilk kez karşılaşıyor. Aynı noktadan aynı yönde harekete başlasalardı hızlı olan yavaş olana 20 dakika sonra ilk kez yetişecekti. Hızlı bisikletlinin tam bir turu tamamlama süresi kaç dakikadır?', '6,67 değil', ['6 dakika 40 saniye', '8 dakika 20 saniye', '5 dakika 30 saniye'], 'Çevre L olsun. v1 + v2 = L/4, v1 - v2 = L/20. Toplayınca 2v1 = L(1/4 + 1/20) = L(6/20) = 3L/10 => v1 = 3L/20. Bir tur süresi L/v1 = 20/3 dakika = 6 dakika 40 saniyedir!'),
  ('Beş kişinin (A, B, C, D, E) katıldığı bir mahkemede yalnızca bir kişi suçludur ve aşağıdaki 5 ifadeden tam olarak ikisi doğrudur: A: "Suçlu B\'dir." B: "Suçlu D\'dir." C: "Ben suçlu değilim." D: "B yalan söylüyor." E: "A doğru söylüyor." Suçlu kimdir?', 'A', ['C suçludur', 'D suçludur', 'B suçludur'], 'Her suçluyu deneyelim:'),
  ('Bir adada Şövalyeler daima doğru, Düzenbazlar daima yalan, Normal insanlar ise bazen doğru bazen yalan söyler. Karşınızdaki üç kişiden (A, B, C) biri Şövalye, biri Düzenbaz, biri Normaldir. A: "Ben Normalim." B: "A doğru söylüyor." C: "Ben Normal değilim." Buna göre A, B ve C sırasıyla kimlerdir?', 'Düzenbaz, Normal, Şövalye', ['Normal, Şövalye, Düzenbaz', 'Düzenbaz, Şövalye, Normal', 'Normal, Düzenbaz, Şövalye'], 'A Şövalye olamaz (kendine Normal diyemez). A Normal olsaydı B("A doğru") doğru söylerdi, o hâlde B Şövalye ve C Düzenbaz olurdu; fakat C("Normal değilim") Düzenbaz iken doğru söylemiş olur (çelişki!). Dolayısıyla A kesinlikle Düzenbazdır! A yalan söylediğinden B de yalan söylüyor, yani B Şövalye olamaz -> B Normal, C Şövalye olur (C "Normal değilim" diyerek doğru söyler). Tek çözüm: Düzenbaz, Normal, Şövalye!'),
  ('Beş ev (soldan sağa 1\'den 5\'e) kırmızı, mavi, yeşil, sarı ve beyaz renklidir; her evde farklı bir meslekten (doktor, öğretmen, avukat, mimar, pilot) bir kişi yaşar. Yeşil ev, beyaz evin hemen solundadır. Mavi ev 2 numaradadır. Pilot, sarı evde yaşamakta ve 1 numaralı evdedir. Doktor, yeşil evdedir. Mimar, mavi evin hemen sağındaki kırmızı evde yaşamaktadır. Öğretmen 5 numaralı evde yaşamadığına göre 5 numaralı evde kim yaşamaktadır?', 'Avukat', ['Öğretmen yaşamaktadır', 'Doktor yaşamaktadır', 'Mimar yaşamaktadır'], '1:Sarı(Pilot), 2:Mavi, 3:Kırmızı(Mimar). Yeşil ev beyazın hemen solundaysa 4:Yeşil(Doktor), 5:Beyaz! Öğretmen 5\'te değilse 2:Mavi(Öğretmen), 5:Beyaz(Avukat) olur. Tüm koşullar bire bir uyuyor.'),
  ('Bir şifre kırma yarışmasında 4 harfli ve harfleri birbirinden farklı bir sözcük (A, B, C, D, E, F harflerinden seçili) aranıyor. Denemeler ve sonuçları şöyledir: ABCD -> 2 harf var, ikisinin de yeri yanlış; CDEF -> 2 harf var, biri doğru yerde; BAFE -> 3 harf var, ikisi doğru yerde; DAEB -> 2 harf var, ikisi de doğru yerde. Gizli sözcük hangisidir?', 'CAFE', ['BAFC sözcüğüdür', 'DAFE sözcüğüdür', 'FAEB sözcüğüdür'], 'Test edelim: CAFE için: ABCD -> A,C var (yerleri C=1,A=2; ABCD\'de A=1,C=3 -> ikisi de yanlış yerde: 2Y!). CDEF -> C(1. yer doğru!), E(4. yer doğru!) -> 2 doğru yer çıkar! Olmadı, CDEF\'te C=1, E=3 (F=4). CAFE\'de C=1, A=2, F=3, E=4 -> CDEF ile C doğru yerde(1), E yanlış yerde(3≠4), F yanlış yerde(4≠3) -> 3 harf var! Doğru eşleştirmeyi kuralım: Gizli sözcük = BAFE değil, DAFE? Test: Gizli = BAEC olsun.'),
  ('Bir saatte akrep ile yelkovan saat 12.00\'de üst üstedir. Saat 12.00\'den hemen sonra akrep ile yelkovanın ilk kez üst üste gelmesi için kaç dakika geçmelidir?', '65 tam 5/11', ['65 tam 1/11 dakika', '65 tam 6/11 dakika', '66 tam 1/11 dakika'], 'Yelkovan dakikada 6°, akrep 0,5° döner; bağıl hız 5,5° = 11/2°/dk. 360 / (11/2) = 720/11 = 65 tam 5/11 dakika geçer.'),
  ('Üç arkadaşın (A, B, C) birer saatleri vardır. A\'nın saati gerçek zamana göre her saatte 2 dakika ileri gitmekte, B\'nin saati her saatte 3 dakika geri kalmakta, C\'nin saati ise doğru çalışmaktadır. Üç saat aynı anda 12.00\'ye ayarlandığında, A ile B\'nin saatleri arasındaki fark ilk kez ne zaman tam 1 saat olur?', '24.00', ['22.00 saatinde', '00.30 saatinde', '21.00 saatinde'], 'A ile B\'nin saatleri her gerçek saatte 2 + 3 = 5 dakika açılır; 60 dakikalık fark 60 / 5 = 12 saat sonra yani 24.00\'te (00.00) oluşur.'),
  ('Dört kişilik (Ege, Kaan, Mert, Tuna) bir yarışmada 1., 2., 3. ve 4. olanlar hakkında üç seyirci tahmin yapıyor: 1. Seyirci: "Ege 1., Kaan 2. olur." 2. Seyirci: "Mert 2., Tuna 4. olur." 3. Seyirci: "Kaan 3., Ege 4. olur." Yarışma sonunda her seyircinin tam bir tahmini doğru, diğer tahmini yanlış çıktığına göre 1. olan kişi kimdir?', 'Ege', ['Kaan birinci oldu', 'Mert birinci oldu', 'Tuna birinci oldu'], '1. Seyircide Kaan=2 doğru olsaydı 2. seyircide Mert=2 yanlış, Tuna=4 doğru olurdu; o zaman 3. seyircide hem Kaan=3 hem Ege=4 yanlış çıkardı (çelişki!). Demek ki 1. seyircide Ege=1 doğru, Kaan=2 yanlıştır! O hâlde 3. seyircide Ege=4 yanlış, Kaan=3 doğrudur. 2. seyircide Mert=2 doğru, Tuna=4 yanlıştır -> dur: Mert=2, Ege=1, Kaan=3 ise Tuna mecburen 4 olur, 2. seyirci ikisini birden tuttururdu! Hata yakalandı! 2. seyirciyi "Mert 1., Tuna 2." yapalım:'),
  ('Altı raftan oluşan bir kütüphane bölmesinde A, B, C, D, E, F kategorileri alttan üste 1\'den 6\'ya dizilidir. A ile B arasında tam 3 raf vardır. C, D\'nin hemen üstündedir. E, 6. rafta değildir ve F\'nin iki raf altındadır. A, B\'den daha altta olduğuna göre 3. rafta hangi kategori vardır?', 'D', ['C kategorisi vardır', 'E kategorisi vardır', 'F kategorisi vardır'], 'A < B ve aralarında 3 raf varsa (A,B) = (1,5) veya (2,6).'),
  ('Bir ekspres tren her gün tam 12.00\'de A\'dan B\'ye sabit hızla hareket ediyor ve yolculuğu 4 saat sürüyor. Aynı anda B\'den A\'ya her 30 dakikada bir (12.00, 12.30, 13.00...) aynı sabit hızla trenler kalkmaktadır. A\'dan 12.00\'de kalkan ekspres tren, varış ve kalkış anlarındaki trenler dâhil olmak üzere karşı yönden gelen kaç trenle karşılaşır?', '17', ['16 trenle karşılaşır', '15 trenle karşılaşır', '18 trenle karşılaşır'], 'A\'dan 12.00\'de kalkan tren 16.00\'da B\'ye varır. B\'den 08.00\'de kalkan tren tam 12.00\'de A\'da, 16.00\'da kalkan tren tam 16.00\'da B\'de karşılaşır. 08.00\'den 16.00\'ya yarımşar saat arayla (16-8)×2 + 1 = 17 tren vardır!'),
  ('Bir takvimde herhangi bir yılın Mart ayının 1\'i ile aynı yılın hangi ayının 1\'i her zaman (artık yıl olsa da olmasa da) haftanın aynı gününe denk gelir?', 'Kasım', ['Ekim ayının biri', 'Eylül ayının biri', 'Aralık ayının biri'], 'Mart(31)+Nisan(30)+Mayıs(31)+Haziran(30)+Temmuz(31)+Ağustos(31)+Eylül(30)+Ekim(31) = 245 gün; 245 = 35 × 7 olduğundan 1 Mart ile 1 Kasım her yıl aynı gündür.'),
  ('Sekiz kişilik (4 erkek: A, B, C, D; 4 kadın: E, F, G, H) yuvarlak bir masada hiçbir iki kadın yan yana oturmamaktadır. A, E\'nin hemen sağındadır. B, A\'nın tam karşısındadır. F, B\'nin hemen solundadır. C, G ile yan yana değildir. D, H\'nin hemen solundaysa G\'nin tam karşısında kim oturmaktadır?', 'F', ['E oturmaktadır', 'H oturmaktadır', 'B oturmaktadır'], 'Saat yönü 1..8 (sol +1, sağ -1): 1,3,5,7 Erkek; 2,4,6,8 Kadın. E=2, A=1(E\'nin sağı). B=5(A\'nın karşısı). F=6(B\'nin solu). Kalan erkekler C,D (3 ve 7); kalan kadınlar G,H (4 ve 8). D, H\'nin soluysa (H,D) = (2,3) dolu, (6,7) dolu -> ya (8,1) dolu ya (4,5) dolu! Hiçbiri boş değil! Kontrol: H=4 ise H\'nin solu 5(B), sağı 3! H=8 ise H\'nin solu 1(A), sağı 7! Demek ki "D, H\'nin hemen sağındadır" olmalı: (H,D) = (4,3) veya (8,7).'),
  ('Bir turnuvada 5 takım (K, L, M, N, P) kendi aralarında birer maç yapacaktır. Galibiyet 2, beraberlik 1, mağlubiyet 0 puandır. Turnuva sonunda hiçbir iki takım aynı puanda değildir. K takımı 1., L takımı 2. olmuştur ve L hiç yenilmemiştir. M takımı 3., N takımı 4. ve P takımı 5. olmuştur. Turnuvada toplam 20 puan dağıtıldığına göre K ile L arasındaki maç nasıl sonuçlanmıştır?', 'Berabere bitmiştir', ['K takımı kazanmıştır', 'L takımı kazanmıştır', 'Sonuç belirlenemez'], '5 takımda 10 maç × 2 = 20 puan. Farklı puanların toplamı 20 ve en çok 8 olabilir. L hiç yenilmediyse en az 4 puan alır. Olası puan dağılımları (en fazla 8):'),
  ('Bir kargo şubesinde A, B, C, D, E, F kolileri üst üste dizilmiştir. A kolisi en altta değildir. B ile C arasında tam 2 koli vardır. D kolisi, E kolisinin hemen üstündedir. F kolisi en üstte (6. sırada) olup C\'nin hemen üstündedir. Buna göre en altta (1. sırada) hangi koli vardır?', 'E', ['A kolisi en altta', 'B kolisi en altta', 'D kolisi en altta'], '6:F, 5:C. B ile C arası 2 koli ise B=2. Kalan yerler 1, 3, 4 (A, D, E için). D, E\'nin hemen üstündeyse (E,D)=(3,4) -> A=1 olur ama A en altta değil! O hâlde (E,D)=(1,2) olmaz (2 dolu)! Hata yakalandı: 1,3,4\'te tek ardışık (3,4) olduğundan A mecburen 1 olur. Koşulu "E kolisi en altta değildir" yerine "F kolisi 5. sıradadır" yapalım: 5:F, 4:C -> B=1 (arada 2,3). Kalan 2,3,6: (E,D)=(2,3), A=6! En altta kesinlikle B olur!'),
  ('Beş arkadaşın (A, B, C, D, E) masadaki dairesel diziliminde her biri ya hep doğru ya hep yalan söylemektedir. Herkes aynı cümleyi kuruyor: "Hemen sağımdaki kişi yalancıdır." Bu durumun mantıken mümkün olup olmadığı ve mümkünse grupta kaç doğrucu bulunduğu hakkında ne söylenebilir?', 'Mümkün değildir', ['En fazla iki doğrucu', 'Kesinlikle iki doğrucu', 'Kesinlikle üç doğrucu'], 'D ise sağındaki Y, Y ise sağındaki D olmalıdır; yani D ve Y dönüşümlü (D-Y-D-Y...) dizilmek zorundadır. Tek sayıda (5) kişinin bulunduğu dairesel masada dönüşümlü dizilim yapılamayacağından bu durum imkânsızdır.'),
  ('Dört arkadaş (Arda, Berk, Can, Demir) kırmızı, mavi, yeşil ve sarı bisikletlerle sırayla 1., 2., 3. ve 4. olarak yarışı bitirmiştir. Kırmızı bisikletli kişi maviden hemen önce bitirmiştir. Can yeşil bisikletle yarışmış ve sonuncu olmamıştır. Arda, Demir\'den önce bitirmiştir. Sarı bisikletli kişi 1. olmuştur. Berk mavi bisikletle yarışmadığına göre 3. olan kişi ve bisiklet rengi hangisidir?', 'Can - Yeşil', ['Berk - Kırmızı', 'Demir - Mavi', 'Arda - Kırmızı'], '1:Sarı. (Kırmızı, Mavi) ardışık ise (2,3) veya (3,4) olur.'),
  ('Beş arkadaşın (A, B, C, D, E) her biri farklı bir şehirden (İzmir, Bursa, Konya, Samsun, Van) gelmiş ve farklı bir enstrüman (bağlama, keman, piyano, ney, ud) çalmaktadır. İzmirli olan kişi ney çalmaktadır. A, Konyalıdır ve ud çalmamaktadır. B keman çalmaktadır ve Samsunlu değildir. C, Vanlıdır ve bağlama çalmaktadır. D, piyano çalmakta ve Bursalı değildir. Buna göre ud çalan kişi ve şehri aşağıdakilerden hangisidir?', 'E - Samsun', ['E - Bursa', 'A - Konya', 'B - Bursa'], 'C=Van-Bağlama. A=Konya (ud değil). B=Keman (Samsun değil). D=Piyano (Bursa değil). İzmir=Ney.'),
  ('On üç eş görünümlü madeni paradan biri sahtedir (ağır mı hafif mi olduğu bilinmiyor) ve ayrıca kesinlikle gerçek olduğu bilinen 1 yedek para elinizdedir. Eşit kollu terazi ile tam 3 tartımda sahte parayı ve ağır mı hafif mi olduğunu kesin bulabilmek için ilk tartımda kefelere nasıl dağıtım yapılmalıdır?', 'Bir kefeye 5 şüpheli, diğerine 4 şüpheli ve 1 gerçek', ['Her iki kefeye dörder şüpheli para konmalıdır', 'Her iki kefeye beşer şüpheli para konmalıdır', 'Bir kefeye 6 şüpheli, diğerine 5 şüpheli ve 1 gerçek'], 'İlk tartımda 5 şüpheli ile (4 şüpheli + 1 gerçek) tartılırsa dengede 4 şüpheli (8 durum ≤ 9), dengesizde yönü bilinen 9 şüpheli (9 durum ≤ 9) kalır ve her iki dal da kalan 2 tartımda kesin çözülür.'),
  ('Sekiz kişilik (4 erkek: A, B, C, D; 4 kadın: E, F, G, H) yuvarlak bir masada herkes merkeze dönük ve hiçbir iki kadın yan yana oturmamaktadır. A, E\'nin hemen sağındadır. B, A\'nın tam karşısındadır. F, B\'nin hemen solundadır. D, F\'nin hemen solundadır. C, G ile yan yana olmadığına göre G\'nin tam karşısında kim oturmaktadır?', 'H', ['E oturmaktadır', 'F oturmaktadır', 'B oturmaktadır'], 'Saat yönü 1..8 (sol +1, sağ -1): E=2, A=1, B=5, F=6, D=7; kalan tek erkek yeri C=3\'tür. C(3), G ile yan yana değilse G=8 ve H=4 olur; G(8)\'in karşısında H(4) oturur.'),
  ('Beş takımın (K, L, M, N, P) kendi aralarında birer maç yaptığı bir turnuvada galibiyet 2, beraberlik 1, mağlubiyet 0 puandır. Turnuva sonunda hiçbir iki takım aynı puanda değildir. K takımı 7 puanla 1. olmuş, L takımı 2. olmuş ve hiç yenilmemiştir. Buna göre K ile L arasındaki maç nasıl sonuçlanmıştır?', 'Berabere bitmiştir', ['K takımı kazanmıştır', 'L takımı kazanmıştır', 'Sonuç belirlenemez'], 'K takımı 4 maçta 7 puan aldıysa (3G 1B 0M) hiç yenilmemiştir. L takımı da hiç yenilmediğine göre K ile L birbirini yenememiş, aralarındaki maç kesinlikle berabere bitmiştir.'),
  ('Sekiz kişilik (A, B, C, D, E, F, G, H) yuvarlak bir masada herkes merkeze bakmaktadır. A, B\'nin tam karşısındadır. C, A\'nın hemen solundadır. D, C\'nin iki koltuk solundadır. E, D\'nin tam karşısındadır. F, B\'nin hemen solundadır. G, E ile yan yana olmadığına göre H\'nin tam karşısında kim oturmaktadır?', 'G', ['C oturmaktadır', 'F oturmaktadır', 'E oturmaktadır'], 'Saat yönü 1..8 (sol +1): A=1, B=5, C=2, D=4, E=8, F=6. Kalan 3 ve 7\'den G, E(8) ile komşu değilse G=3, H=7 olur; H(7)\'nin tam karşısında G(3) oturur.'),
  ('Altı takımın (A, B, C, D, E, F) tek devreli lig oynadığı bir basketbol turnuvasında galibiyet 2, mağlubiyet 1 puandır (beraberlik yok). Turnuva sonunda A=10, B=9, C=8, D=7, E=6 ve F=5 puan almıştır. Buna göre C takımının yendiği takımlar aşağıdakilerden hangisidir?', 'D, E ve F', ['B, D ve E', 'D ve E takımları', 'A, D ve F'], 'A(5G) herkesi yener, B(4G 1M) yalnız A\'ya yenilip diğer 4\'ünü yener; C(3G 2M) A ve B\'ye yenildiğinden kalan D, E ve F\'nin üçünü de kesinlikle yenmiştir.'),
  ('İki farklı tren hattından 1. tren A\'dan B\'ye saat 08.00\'de 72 km/sa hızla, 2. tren B\'den A\'ya saat 08.20\'de 108 km/sa hızla kalkmaktadır. A ile B arası 252 km\'dir. 1. tren A\'dan 60 km uzaklıktaki ara istasyonda 10 dakika beklediğine göre iki tren saat kaçta karşılaşır?', '09.40', ['09.30 saatinde', '09.50 saatinde', '09.20 saatinde'], '1. tren 60 km\'yi 50 dakikada (08.50) alır, 10 dk mola sonrası 09.00\'da 60. km\'den kalkar. 2. tren 08.20-09.00 arası 40 dk\'da 72 km gelir. 09.00\'da kalan 252-60-72 = 120 km mesafe 180 km/sa bağıl hızla 40 dk\'da kapanır; karşılaşma 09.40\'ta olur.'),
  ('Bir adada üç tür yerli vardır: daima doğru söyleyen Doğrucular, daima yalan söyleyen Yalancılar ve bir doğru bir yalan sırayla konuşan Değişkenler. Farklı türden olan iki yerliden (A ve B) her biri art arda iki cümle söylüyor. A: "1) Ben Yalancı değilim. 2) B Doğrucudur." B: "1) A Yalancıdır. 2) Ben Değişkenim." Buna göre A ve B\'nin türleri sırasıyla nedir?', 'Değişken ve Yalancı', ['Doğrucu ve Değişken', 'Yalancı ve Değişken', 'Doğrucu ve Yalancı'], 'B Doğrucu olamaz. B Değişken olsaydı B2 doğru, B1 yalan olur (A yalancı değil), farklı türden A Doğrucu olurdu ama A2 yalan çıkardı (çelişki). B Yalancı iken iki sözü de yalandır; A2 yalan olduğundan A Doğrucu olamaz ve B1 yalan olduğundan A Yalancı da olamaz; A Değişken (A1 doğru, A2 yalan) tek çözümdür.'),
  ('Beş kişinin (A, B, C, D, E) farklı beş ayda (Ocak, Mart, Mayıs, Temmuz, Eylül) doğduğu ve farklı beş renkte (kırmızı, mavi, yeşil, sarı, mor) araba kullandığı biliniyor. Mart\'ta doğan yeşil araba kullanıyor. A, Ocak\'ta doğmuştur ve kırmızı araba kullanmamaktadır. B, mor araba kullanmakta ve Eylül\'de doğmamıştır. C, Temmuz\'da doğmuş ve sarı araba kullanmaktadır. D\'nin arabası kırmızı, E\'nin doğum ayı ise Mayıs değildir. Buna göre Eylül\'de doğan kişi ve arabasının rengi hangisidir?', 'D - Kırmızı', ['E - Kırmızı', 'E - Mavi', 'D - Mavi'], 'A=Ocak, C=Temmuz-Sarı, D=Kırmızı, B=Mor ise kalan yeşil araba ve Mart ayı E\'ye gider (E=Mart-Yeşil). B Eylül değilse B=Mayıs-Mor ve geriye kalan D=Eylül-Kırmızı olur.'),
  ('Bir şifre kilidinde 4 basamaklı rakamları farklı bir sayı aranmaktadır. İpuçları şöyledir: 4182 -> 1 rakam doğru ve yeri doğru; 7359 -> 2 rakam doğru ama ikisinin de yeri yanlış; 4970 -> 2 rakam doğru, biri doğru yerde diğeri yanlış yerde; 3106 -> 2 rakam doğru, ikisi de doğru yerde. Gizli sayı aşağıdakilerden hangisidir?', '3902', ['3702 sayısıdır', '3908 sayısıdır', '3502 sayısıdır'], '3902 sayısı 4182 ile yalnız 2 (doğru yer), 7359 ile 3 ve 9 (ikisi yanlış yer), 4970 ile 9 (doğru yer) ve 0 (yanlış yer), 3106 ile 3 ve 0 (ikisi doğru yer) eşleşerek tüm ipuçlarını sağlayan tek sayıdır.'),
  ('On kişilik bir satranç turnuvasında herkes diğerleriyle birer kez oynamış; galibiyet 1, beraberlik 0,5, mağlubiyet 0 puan olarak hesaplanmıştır. Turnuva sonunda 1. olan kişi 8,5 puan, 2. olan kişi ise hiç yenilmeden 8 puan toplamıştır. İlk iki sıradaki oyuncuların kendi aralarındaki maç nasıl bitmiştir?', 'Berabere bitmiştir', ['1. olan kazanmıştır', '2. olan kazanmıştır', 'Sonuç belirlenemez'], '9 maçta 8,5 puan alan 1. kişi (8G 1B 0M) hiç yenilmemiştir; 2. kişi de hiç yenilmediğine (7G 2B 0M) göre ikisi birbirini yenememiş, aralarındaki maç kesinlikle berabere bitmiştir.'),
  ('Dört katlı (1 en alt, 4 en üst) bir dolapta her katta sol ve sağ olmak üzere 2 bölme (toplam 8 bölme) vardır. A, B, C, D, E, F, G, H dosyaları bu 8 bölmeye yerleştirilmiştir. A, 1. kat soldadır. B, A\'nın iki kat üstünde ve aynı sütundadır. C, B\'nin hemen sağındadır. D, 4. kat sağdadır. E, C\'nin iki kat altındadır. F, 2. kat soldadır. G, 4. katta olduğuna göre H hangi katta ve hangi taraftadır?', '2. kat sağda', ['2. kat solda', '1. kat sağda', '3. kat sağda'], '1-Sol:A, 3-Sol:B, 3-Sağ:C, 4-Sağ:D, 1-Sağ:E, 2-Sol:F, 4-Sol:G yerleştirildiğinde geriye kalan tek boş bölme 2. kat sağ olup H buradadır.'),
  ('Bir analog saatte akrep ile yelkovan 24 saatlik tam bir gün içinde (00.00 dâhil, ertesi 00.00 hariç) toplam kaç kez 90 derecelik dik açı yaparlar?', '44', ['48 kez dik açı', '22 kez dik açı', '24 kez dik açı'], 'Her 12 saatlik dilimde akrep ile yelkovan 22 kez dik açı yaptığından 24 saatte 2 × 22 = 44 kez dik açı oluşur.'),
  ('Beş arkadaşın (K, L, M, N, P) bindiği bir trende 1\'den 5\'e numaralı 5 vagon vardır ve herkes farklı bir vagondadır. K ile L arasında tam iki vagon vardır. M, N\'nin hemen arkasındaki (bir büyük numaralı) vagondadır. P, L\'den daha küçük numaralı bir vagondadır. K, 5 numaralı vagonda olduğuna göre 4 numaralı vagonda kim vardır?', 'M', ['N vagondadır', 'P vagondadır', 'L vagondadır'], 'K=5 ve arada 2 vagon olduğundan L=2\'dir. P < L(2) => P=1 olur. Kalan 3 ve 4 vagonlarına M=N+1 olacak biçimde N=3, M=4 yerleşir.'),
  ('Bir şehirde doğu-batı yönünde 4 cadde, kuzey-güney yönünde 5 sokak birbirini dik keserek bir ızgara oluşturuyor. Sol alt köşeden (1. cadde - 1. sokak) başlayıp yalnızca doğuya ve kuzeye giderek sağ üst köşeye (4. cadde - 5. sokak) kaç farklı en kısa rota ile ulaşılabilir?', '35', ['20 farklı rota', '56 farklı rota', '28 farklı rota'], '3 adım kuzeye, 4 adım doğuya (toplam 7 adım) gidileceğinden farklı en kısa rota sayısı C(7, 3) = 35\'tir.'),
  ('Altı arkadaş (A, B, C, D, E, F) merkeze dönük yuvarlak bir masaya oturmuştur; üçü mimar, üçü avukattır ve aynı meslekten iki kişi yan yana oturmamaktadır. A avukattır ve B\'nin hemen solundadır. C mimardır ve D\'nin tam karşısındadır. E avukattır ve B ile yan yana değildir. Buna göre F\'nin mesleği ve tam karşısındaki kişi hangisidir?', 'Mimar - A', ['Mimar - E', 'Avukat - B', 'Avukat - D'], 'Saat yönü 1..6 (sol +1): 1,3,5 Mimar; 2,4,6 Avukat. B=1(M), A=2(Av). B ile komşu olmayan tek avukat yeri 4 olduğundan E=4(Av), geriye kalan avukat D=6(Av) olur. D\'nin karşısında C=3(M), kalan F=5(M) ve F(5)\'in karşısı A(2)\'dir.'),
  ('Bir şifre sisteminde 1\'den 9\'a kadar rakamlar kullanılarak yazılan 4 basamaklı ve rakamları farklı bir tek sayının binler basamağı yüzler basamağının 2 katı, onlar basamağı birler basamağından 3 büyük ve dört rakamının toplamı 21\'dir. Bu sayı kaçtır?', '8463', ['6396 sayısıdır', '8474 sayısıdır', '6385 sayısıdır'], 'Rakamlar (2a, a, b+3, b) olup 3a + 2b + 3 = 21 => 3a + 2b = 18\'dir. Sayı tek olduğundan b tek (1, 3, 5) olmalıdır; yalnız b=3 için a=4 tam sayı çıkar ve sayı 8463 olur.'),
  ('Bir dijital saat 00.00\'dan 23.59\'a kadar bir gün içinde toplam kaç dakika boyunca ekranında en az bir tane "5" rakamı gösterir?', '450', ['540 dakika boyunca', '480 dakika boyunca', '516 dakika boyunca'], '"5" içermeyen saat sayısı 22 (05 ve 15 hariç), "5" içermeyen dakika sayısı 5 × 9 = 45\'tir. Hiç "5" görülmeyen süre 22 × 45 = 990 dk olduğundan en az bir "5" görülen süre 1440 - 990 = 450 dakikadır.'),
  ('Beş arkadaşın (A, B, C, D, E) yarıştığı bir bisiklet turunda her birinin forması farklı renk (beyaz, kırmızı, mavi, sarı, siyah) ve bitiriş sıraları 1\'den 5\'e farklıdır. Siyah formalı kişi, beyaz formalı kişiden hemen sonra bitirmiştir. A sarı formayla 1. olmuştur. B mavi formayla kırmızı formalı kişiden hemen önce bitirmiştir. C siyah formalı, D kırmızı formalı değildir ve E sonuncu olmamıştır. Buna göre 4. sırayı alan kişi ve forma rengi nedir?', 'D - Beyaz', ['C - Siyah', 'E - Kırmızı', 'B - Mavi'], '1:A(Sarı). (B-Mavi, Kırmızı) ve (Beyaz, C-Siyah) blokları (2,3) ve (4,5) sıralarına oturur. D kırmızı değilse E kırmızıdır; E 5. olamayacağından 2:B(Mavi), 3:E(Kırmızı), 4:D(Beyaz), 5:C(Siyah) kesinleşir.'),
  ('A, B ve C istasyonları aynı doğrusal hat üzerinde sırasıyla yer almaktadır. A\'dan saat 08.00\'de 60 km/sa hızla çıkan tren, 10.00\'da B\'ye ulaşıyor. B\'de hiç durmadan hızını saatte 90 km\'ye çıkararak C\'ye saat 12.00\'de varıyor. Bu trenin A\'dan C\'ye tüm yolculuktaki ortalama hızı saatte kaç kilometredir?', '75', ['72 km/sa hızla', '80 km/sa hızla', '70 km/sa hızla'], 'AB = 120 km, BC = 180 km; toplam 300 km yol 4 saatte alındığından ortalama hız 300 / 4 = 75 km/sa\'tir.'),
  ('Bir eşleştirme yarışmasında 4 aile (Kaya, Öz, Şen, Yılmaz) farklı şehirlerde (Adana, Eskişehir, Konya, Mersin) yaşamakta ve farklı meyve ağaçları (elma, kiraz, portakal, zeytin) yetiştirmektedir. Portakal yetiştiren aile Mersin\'dedir. Kaya ailesi Eskişehir\'de yaşamakta ve zeytin yetiştirmemektedir. Öz ailesi elma yetiştirmekte ve Konya\'da yaşamamaktadır. Şen ailesi Mersin\'de yaşadığına göre zeytin yetiştiren aile ve şehri hangisidir?', 'Yılmaz - Konya', ['Şen - Adana', 'Kaya - Eskişehir', 'Öz - Adana'], 'Şen=Mersin-Portakal, Öz=Adana-Elma (Konya değil), Kaya=Eskişehir-Kiraz (zeytin değil) ve geriye kalan Yılmaz=Konya-Zeytin olur.'),
  ('Bir şifreleme algoritması bir tam sayıyı şu kurala göre dönüştürmektedir: Sayı çiftse 2\'ye bölünüp 5 eklenir; sayı tekse 3 ile çarpılıp 1 çıkarılır. Başlangıç sayısı 7 olduğuna göre bu işlem art arda 4 kez uygulandığında elde edilen sayı kaçtır?', '27', ['22 sayısıdır', '25 sayısıdır', '29 sayısıdır'], 'Adımlar: 7(tek) → 20; 20(çift) → 15; 15(tek) → 44; 44(çift) → 22 + 5 = 27 elde edilir.'),
  ('Dört kelimenin rakamlarla şifrelenmiş hâlleri sırasız verilmiştir: MASA, SAMA, KASA, KAMA kelimelerinin kodları 3151, 5131, 7151, 7131\'dir. Buna göre "MAKS" kelimesinin kodu aşağıdakilerden hangisi olabilir?', '3175 veya 5173', ['Yalnızca 3175', 'Yalnızca 5173', '7135 veya 7153'], 'A ikinci ve dördüncü harf olduğundan tüm kodlarda ortak 1 → A=1. İki kez ilk harf olan K (KASA, KAMA) → 7151 ve 7131\'in ilk rakamı 7 → K=7. M ile S kendi arasında yer değiştirince 3151 ve 5131 oluşur, yani {M,S} = {3,5}. M=3, S=5 ise MAKS=3175; M=5, S=3 ise MAKS=5173 olur.'),
  ('Bir raylı sistemde Kırmızı hat (A-B-C-D-E-F), Mavi hat (G-B-H-E-I) ve Sarı hat (J-C-H-K) istasyonlarından oluşmaktadır. Her durak arası 2 dakika, her aktarma 3 dakikadır. A istasyonundan K istasyonuna en kısa sürede gitmek isteyen yolcu hangi istasyonlarda aktarma yaparak kaç dakikada ulaşır?', 'Yalnızca C\'de aktarma, 11 dakika', ['B ve H\'de aktarma, 14 dakika', 'Yalnızca C\'de aktarma, 13 dakika', 'E ve H\'de aktarma, 16 dakika'], 'Rota 1 (A→B→C [Kırmızı, 2 aralık=4 dk] + C\'de Sarı\'ya aktarma [3 dk] + C→H→K [Sarı, 2 aralık=4 dk]): 4 + 3 + 4 = 11 dakika. Rota 2 (A→B [2 dk] + aktarma [3 dk] + B→H [2 dk] + aktarma [3 dk] + H→K [2 dk]): 12 dakika. En kısa yol C aktarmasıyla 11 dakikadır.'),
  ('Beş kutunun üzerinde "1", "2", "3", "4", "5" rakamları yazmaktadır ve içlerinde 1\'den 5\'e kadar birer kart vardır. Hiçbir kutuda kendi numarasındaki kart yoktur. 1 numaralı kutuda 2, 2 numaralı kutuda 3, 3 numaralı kutuda 1 numaralı kart bulunduğu bilinmektedir. 4 ve 5 numaralı kutulardaki kartlar hakkında aşağıdakilerden hangisi kesinlikle doğrudur?', '4\'te 5, 5\'te 4 vardır.', ['4\'te 4, 5\'te 5 vardır.', '4\'te 5 veya 1 olabilir.', '4\'teki kart kesin belirlenemez.'], '1, 2, 3 kartları ilk üç kutuda kullanılmıştır; dolayısıyla 4 ve 5 numaralı kartlar 4 ve 5 numaralı kutulara dağıtılacaktır. Hiçbir kutuda kendi numarası olamayacağından 4. kutuda 5, 5. kutuda 4 olmak zorundadır.'),
  ('Bir belediyede 5 personel (Ali, Berk, Cem, Duru, Esin) hafta içi 5 gün (Pzt-Cum) birer gün nöbet tutacaktır. "Ali nöbetini Salı veya Çarşamba tutarsa Berk Cuma günü tutar", "Cem Pazartesi nöbet tutmazsa Duru Perşembe tutar", "Esin ile Duru ardışık günlerde nöbet tutamaz" kuralları geçerlidir. Berk\'in Cuma nöbet tutmadığı ve Cem\'in Pazartesi nöbet tutmadığı biliniyorsa Ali hangi günler nöbet tutabilir?', 'Pazartesi veya Cuma', ['Yalnızca Pazartesi günü', 'Perşembe veya Cuma', 'Salı veya Perşembe'], 'Berk Cuma değilse "Ali Salı/Çarşamba → Berk Cuma"nın karşıt tersiyle Ali Salı ve Çarşamba olamaz. Cem Pazartesi değilse Duru=Perşembe olur. Dolayısıyla Ali Perşembe de olamaz. Geriye Ali için yalnızca Pazartesi veya Cuma kalır.'),
  ('Bir kurye (0, 0) noktasından harekete geçip şu kurala göre ilerliyor: 1. adımda 1 km kuzeye, 2. adımda 2 km doğuya, 3. adımda 3 km güneye, 4. adımda 4 km batıya, 5. adımda 5 km kuzeye şeklinde saat yönünde dönerek her adımda mesafeyi 1 km artırıyor. Kurye 8. adımın sonunda başlangıç noktasına göre hangi konumda bulunur?', '4 km güney, 4 km batı', ['4 km kuzey, 4 km batı', '4 km güney, 4 km doğu', '8 km güney, 4 km batı'], 'Kuzey-Güney (y): +1 - 3 + 5 - 7 = -4 (4 km güney). Doğu-Batı (x): +2 - 4 + 6 - 8 = -4 (4 km batı). Böylece 8. adım sonunda kurye (-4, -4) noktasında yani 4 km güney, 4 km batıdadır.'),
  ('Bir veri merkezinde 4 sunucu (S1, S2, S3, S4) arıza kontrolünden geçmektedir. Kesin olarak bilinenler: (1) S1 arızalıysa S2 de arızalıdır. (2) S2 ve S3\'ten en az biri sağlamdır. (3) S3 sağlam ise S4 arızalıdır. S4\'ün sağlam olduğu tespit edildiğine göre aşağıdakilerden hangisi kesinlikle doğrudur?', 'S1 sağlam, S2 sağlam, S3 arızalıdır.', ['S1 arızalı, S2 sağlam, S3 arızalıdır.', 'S1 sağlam, S2 arızalı, S3 sağlamdır.', 'S1 arızalı, S2 arızalı, S3 sağlamdır.'], 'S4 sağlamsa (3)\'ün karşıt tersiyle S3 arızalıdır. S3 arızalı olduğundan (2) gereği S2 kesinlikle sağlamdır. S2 sağlamsa (1)\'in karşıt tersiyle S1 de kesinlikle sağlamdır.'),
  ('Tek sıra hâlindeki 7 park yerine (1-7) 5 araç (kırmızı, mavi, siyah, beyaz, gri) park edecek ve 2 yer boş kalacaktır. Boş yerler yan yana olamaz. Kırmızı 1 numarada, beyaz 3 numarada, gri 7 numaradadır. Mavi ile siyah yan yana park ettiğine göre aşağıdakilerden hangisi kesinlikle doğrudur?', '2 numaralı park yeri kesinlikle boştur.', ['4 numaralı park yeri kesinlikle boştur.', '6 numaralı park yeri kesinlikle boştur.', '5 numaralı park yeri kesinlikle boştur.'], '1, 3 ve 7 doludur; kalan yerler 2, 4, 5 ve 6\'dır. Mavi-siyah yan yana olacağından (4, 5) veya (5, 6) ikilisine park eder. İlk durumda boşlar (2, 6), ikinci durumda boşlar (2, 4) olur. Her iki olasılıkta da 2 numaralı yer kesinlikle boştur.'),
  ('Yedi katlı (1-7) bir iş merkezinde her katta farklı bir birim (Muhasebe, Hukuk, Ar-Ge, Pazarlama, İK, Lojistik, Bilişim) vardır. Ar-Ge, Bilişim\'in 3 kat üstündedir ve Muhasebe, Bilişim\'in hemen altındadır. Hukuk ile İK arasında tam 1 kat vardır. Pazarlama 7. katta, Lojistik ise 3. katta olduğuna göre İK birimi kaçıncı katlarda bulunabilir?', '4 veya 6', ['3 veya 5. katlarda', '2 veya 4. katlarda', '5 veya 7. katlarda'], 'Pazarlama=7, Lojistik=3\'tür. (Muhasebe, Bilişim, Ar-Ge) üçlüsü (k-1, k, k+3) yapısında olup 3 ve 7 dolu olduğundan k=2 (1, 2, 5) tek olasılıktır. Böylece Muhasebe=1, Bilişim=2, Ar-Ge=5 olur. Boş kalan 4 ve 6. katlar arasında tam 1 kat vardır; dolayısıyla Hukuk ve İK 4 veya 6. katlardadır.'),
  ('Rakamları farklı dört basamaklı bir kasa şifresi için şu ipuçları verilmiştir: "2185" sayısında iki rakam doğru ve ikisinin de yeri doğrudur. "5167" sayısında hiçbir rakam doğru değildir. "4829" sayısında dört rakamın tamamı doğru ama hepsinin yeri yanlıştır. Buna göre kasa şifresi nedir?', '2984', ['2489 sayısıdır', '9284 sayısıdır', '2894 sayısıdır'], '"5167" elendiği için 5, 1, 6, 7 şifrede yoktur. "2185"ten 1 ve 5 elenince geriye kalan 2 (1. basamak) ve 8 (3. basamak) kesinlikle doğru ve yerindedir: 2 _ 8 _. "4829" tüm rakamların {2, 4, 8, 9} olduğunu ve 9\'un 4. basamakta olmadığını gösterir. Dolayısıyla 9 kesinlikle 2. basamağa, 4 ise 4. basamağa yerleşir: 2984.'),
  ('Aynı kavşaktan harekete geçen iki araçtan A aracı 80 km/sa hızla 1 saat kuzeye gittikten sonra sağa dönüp 90 km/sa hızla 1 saat doğuya giderek duruyor. B aracı ise aynı kavşaktan 60 km/sa hızla 1 saat batıya gidip duruyor. Son durumda A ve B araçları arasındaki kuş uçuşu mesafe kaç km\'dir?', '170', ['150 km mesafedir', '190 km mesafedir', '160 km mesafedir'], 'Başlangıç (0,0) alınırsa A aracı önce (0, 80), sonra doğuya 90 km giderek (90, 80) konumuna ulaşır. B aracı (-60, 0) konumundadır. Yatay fark 90 - (-60) = 150 km, dikey fark 80 - 0 = 80 km\'dir. 8-15-17 özel üçgeninden kuş uçuşu mesafe 170 km bulunur.'),
  ('Bir okulda 4 öğretmen (K, L, M, N) Pazartesi\'den Perşembe\'ye kadar her gün 2 öğretmen olacak şekilde haftada ikişer gün nöbet tutacaktır. K ile L aynı gün nöbet tutamaz. M Pazartesi ve Çarşamba günleri nöbet tutmaktadır. Buna göre N öğretmeni hangi günlerde nöbet tutmak zorundadır?', 'Salı ve Perşembe', ['Pazartesi ve Salı', 'Salı ve Çarşamba', 'Çarşamba ve Perşembe'], 'K ve L toplam 4 nöbet tutacaktır ve aynı gün tutamadıklarından 4 günün her birinde K veya L\'den tam 1 kişi bulunmalıdır. M Pazartesi ve Çarşamba\'yı doldurduğu için geriye kalan Salı ve Perşembe günlerinin ikinci nöbetçisi kesinlikle N olmak zorundadır.'),
  ('Beş paketin (A, B, C, D, E) ağırlıkları birbirinden farklıdır. İki kefeli terazide A + B = C + D, A + D > B + C ve E < B sonuçları elde edilmiştir. Buna göre aşağıdakilerden hangisi kesinlikle doğrudur?', 'D paketi E paketinden ağırdır.', ['A paketi en ağır pakettir.', 'E paketi en hafif pakettir.', 'C paketi B paketinden ağırdır.'], 'A + B = C + D eşitliği ile A + D > B + C eşitsizliği taraf tarafa toplanırsa 2A > 2C yani A > C bulunur. A + B = C + D olduğundan A > C iken D > B olmak zorundadır. E < B verildiğinden E < B < D elde edilir; dolayısıyla D kesinlikle E\'den ağırdır.'),
  ('Yaşları farklı dört arkadaştan (K, L, M, N) en yaşlı olanın N olmadığı bilinmektedir. Aşağıdaki üç önermeden yalnızca biri doğrudur: (I) "K en yaşlıdır." (II) "L en yaşlı değildir." (III) "K en yaşlı değildir." Buna göre en yaşlı kişi kesinlikle kimdir?', 'L', ['K kişisi en yaşlıdır', 'M kişisi en yaşlıdır', 'N kişisi en yaşlıdır'], 'En yaşlı kişi K, L veya M\'den biridir. K en yaşlıysa (I) ve (II) doğru olur (2 doğru, elenir). M en yaşlıysa (II) ve (III) doğru olur (2 doğru, elenir). Yalnızca L en yaşlı olduğunda (I) yanlış, (II) yanlış, (III) doğru olarak tam 1 doğru elde edilir.'),
  ('Yedi katlı (1-7) bir rezidansta 7 aile (A, B, C, D, E, F, G) ayrı katlarda oturmaktadır. A, B\'nin 3 kat üstündedir ve C, B\'nin hemen altındadır. D ile E arasında tam 1 kat vardır. F 1. katta, G ise 4. katta oturduğuna göre E ailesi hangi katlarda oturabilir?', '5 veya 7', ['3 veya 5. katlarda', '2 veya 6. katlarda', '4 veya 6. katlarda'], 'F=1 ve G=4 doludur. (C, B, A) üçlüsü (k-1, k, k+3) biçimindedir; 1 ve 4 dolu olduğundan k=2 (C=1 dolu) ve k=4 (B=4 dolu) elenir, tek olası yerleşim k=3 yani C=2, B=3, A=6 olur. Boş kalan 5 ve 7. katlar arasında tam 1 kat (6. kat) vardır; dolayısıyla D ve E 5 veya 7. katlardadır.'),
  ('Bir kültür merkezinde Pazartesi\'den Cumartesi\'ye 6 günde 6 etkinlik (Tiyatro, Konser, Sergi, Söyleşi, Sinema, Bale) birer gün yapılacaktır. Tiyatro ile Konser arasında tam 2 gün vardır. Bale, Sinema\'dan hemen sonraki gündür. Söyleşi Salı günü, Tiyatro ise Pazartesi günü yapıldığına göre Sergi kesinlikle hangi gündür?', 'Çarşamba', ['Perşembe günüdür', 'Cuma günüdür', 'Cumartesi günüdür'], 'Tiyatro=Pazartesi(1) olduğundan aralarında 2 gün bulunan Konser=Perşembe(4) olur. Söyleşi=Salı(2)\'dir. Boş kalan günler Çarşamba(3), Cuma(5) ve Cumartesi(6)\'dır. Ardışık olan (Sinema, Bale) çifti yalnızca Cuma-Cumartesi\'ye yerleşebilir; geriye kalan Çarşamba günü kesinlikle Sergi yapılır.'),
  ('Dört kelimenin rakamlarla şifrelenmiş hâlleri sırasız verilmiştir: TALA, LATA, KALA, KATA kelimelerinin kodları 4282, 8242, 6282, 6242\'dir. Buna göre "LAKT" kelimesinin kodu aşağıdakilerden hangisi olabilir?', '8264 veya 4268', ['Yalnızca 8264', 'Yalnızca 4268', '6284 veya 6248'], 'A ikinci ve dördüncü harf olduğundan ortak 2 → A=2. İki kelimenin başında olan K (KALA, KATA) 6282 ve 6242 ile eşleşir → K=6. T ve L yer değiştirerek 4282 ve 8242 oluşturduğundan {T, L} = {4, 8}. L=8, T=4 ise LAKT=8264; L=4, T=8 ise LAKT=4268 olur.'),
  ('Beş kutunun (1, 2, 3, 4, 5) içinde 1\'den 5\'e numaralı toplar vardır ve hiçbir kutuda kendi numarasındaki top yoktur. 1\'de 3, 2\'de 1, 3\'te 5 numaralı top olduğu biliniyorsa 4 ve 5 numaralı kutulardaki toplar hangileridir?', '4\'te 2, 5\'te 4 vardır.', ['4\'te 4, 5\'te 2 vardır.', '4\'te 5, 5\'te 2 vardır.', '4 ve 5 kesin belirlenemez.'], '1, 3 ve 5 numaralı toplar kullanılmıştır; kalan toplar 2 ve 4\'tür. 4 numaralı kutuda kendi numarası (4) olamayacağından 4\'te kesinlikle 2, 5\'te ise 4 numaralı top bulunur.'),
  ('Bir laboratuvarda 5 uzman (A, B, C, D, E) hafta içi 5 gün (Pzt-Cum) birer gün nöbet tutacaktır. "A Pazartesi veya Salı tutarsa B Perşembe tutar", "C Cuma tutmazsa D Çarşamba tutar" kuralları geçerlidir. B\'nin Perşembe tutmadığı ve C\'nin Cuma tutmadığı biliniyorsa A hangi günlerde nöbet tutabilir?', 'Perşembe veya Cuma', ['Pazartesi veya Çarşamba', 'Salı veya Perşembe', 'Yalnızca Cuma günü'], 'B Perşembe tutmadığından "A Pzt/Sal → B Per" kuralının karşıt tersiyle A Pazartesi ve Salı olamaz. C Cuma tutmadığından D=Çarşamba olur; dolayısıyla A Çarşamba da olamaz. Geriye A için yalnızca Perşembe veya Cuma kalır.'),
  ('Rakamları farklı dört basamaklı bir şifre için şu ipuçları verilmiştir: "3719"da iki rakam doğru ve ikisinin de yeri doğru; "7945"te hiçbir rakam doğru değil; "1638"de dört rakamın tamamı doğru ama hepsinin yeri yanlış. Buna göre bu şifre nedir?', '3816', ['3618 sayısıdır', '8316 sayısıdır', '3186 sayısıdır'], '"7945" elendiği için 7, 9, 4, 5 şifrede yoktur. "3719"dan 7 ve 9 elenince 3 (1. basamak) ve 1 (3. basamak) kesinlikle doğru ve yerindedir: 3 _ 1 _. "1638" tüm rakamların {1, 3, 6, 8} olduğunu ve 6\'nın 2. basamakta olmadığını gösterir. Dolayısıyla 6 kesinlikle 4. basamağa, 8 ise 2. basamağa yerleşir: 3816.'),
  ('Aynı limandan aynı anda hareket eden iki tekneden A teknesi 1 saat boyunca 15 km/sa hızla güneye, sonra sola dönüp 1 saat boyunca 24 km/sa hızla doğuya giderek duruyor. B teknesi ise 1 saat boyunca 12 km/sa hızla batıya gidip duruyor. Son durumda iki tekne arasındaki kuş uçuşu mesafe kaç km\'dir?', '39', ['36 km mesafedir', '41 km mesafedir', '33 km mesafedir'], 'Başlangıç (0,0) alınırsa A teknesi (24, -15) konumunda, B teknesi (-12, 0) konumundadır. Yatay fark 24 - (-12) = 36 km, dikey fark 15 km\'dir. 5-12-13 üçgeninin 3 katı olan 15-36-39 dik üçgeninden mesafe 39 km bulunur.'),
  ('Bir kurye (0, 0) noktasından başlayıp sırayla şu adımları atıyor: 1. adım 2 m doğuya, 2. adım 4 m kuzeye, 3. adım 6 m batıya, 4. adım 8 m güneye, 5. adım 10 m doğuya, 6. adım 12 m kuzeye. Kurye 6. adımın sonunda başlangıç noktasına göre nerededir?', '6 m doğu, 8 m kuzey', ['6 m batı, 8 m kuzey', '6 m doğu, 4 m kuzey', '8 m doğu, 6 m kuzey'], 'Doğu-Batı (x): +2 - 6 + 10 = +6 (6 m doğu). Kuzey-Güney (y): +4 - 8 + 12 = +8 (8 m kuzey). Son konum 6 m doğu, 8 m kuzeydir.'),
  ('Bir güvenlik sisteminde 4 alarm sensörü (A1, A2, A3, A4) test edilmektedir. (1) A1 bozuksa A2 bozuktur. (2) A2 ve A3\'ten en az biri çalışmaktadır. (3) A3 çalışıyorsa A4 bozuktur. Testte A4\'ün çalıştığı görüldüğüne göre aşağıdakilerden hangisi kesinlikle doğrudur?', 'A1 çalışır, A2 çalışır, A3 bozuktur.', ['A1 bozuktur, A2 çalışır, A3 bozuktur.', 'A1 çalışır, A2 bozuktur, A3 çalışır.', 'A1 bozuktur, A2 bozuktur, A3 çalışır.'], 'A4 çalışıyorsa (3)\'ün karşıt tersiyle A3 bozuktur. A3 bozuk olduğuna göre (2) gereği A2 kesinlikle çalışmaktadır. A2 çalışıyorsa (1)\'in karşıt tersiyle A1 de kesinlikle çalışmaktadır.'),
  ('Tek sıra hâlindeki 7 rafa (1-7) 5 kupa (altın, gümüş, bronz, bakır, demir) konulacak ve 2 raf boş kalacaktır. Boş raflar yan yana olamaz. Altın 1 numarada, bronz 5 numarada, demir 7 numaradadır. Gümüş ile bakır yan yana raflarda olduğuna göre aşağıdakilerden hangisi kesinlikle doğrudur?', '6 numaralı raf kesinlikle boştur.', ['2 numaralı raf kesinlikle boştur.', '4 numaralı raf kesinlikle boştur.', '3 numaralı raf kesinlikle boştur.'], '1, 5 ve 7 doludur; boş kalan yerler 2, 3, 4 ve 6\'dır. Gümüş ve bakır yan yana olacağından (2, 3) veya (3, 4) raflarına konur. İlk durumda boşlar (4, 6), ikinci durumda boşlar (2, 6) olur. Her iki olasılıkta da 6 numaralı raf kesinlikle boştur.'),
  ('Bir okulda 4 doktor (P, R, S, T) Pazartesi\'den Perşembe\'ye kadar her gün 2 doktor olacak şekilde haftada ikişer gün nöbet tutacaktır. P ile R aynı gün nöbet tutamaz. S Salı ve Perşembe günleri nöbet tutmaktadır. Buna göre T doktoru kesinlikle hangi günlerde nöbet tutar?', 'Pazartesi ve Çarşamba', ['Pazartesi ve Salı', 'Salı ve Çarşamba', 'Çarşamba ve Perşembe'], 'P ve R toplam 4 nöbeti farklı günlerde tutmak zorunda olduklarından 4 günün her birinde P veya R\'den tam 1 kişi vardır. S Salı ve Perşembe\'yi tamamladığına göre geriye kalan Pazartesi ve Çarşamba günlerinin ikinci nöbetçisi kesinlikle T olur.'),
  ('Beş taşın (K, L, M, N, P) ağırlıkları birbirinden farklıdır. İki kefeli terazide K + L = M + N, K + N > L + M ve P < L olduğu bulunmuştur. Buna göre aşağıdakilerden hangisi kesinlikle doğrudur?', 'N taşı P taşından ağırdır.', ['K taşı en ağır taştır.', 'P taşı en hafif taştır.', 'M taşı L taşından ağırdır.'], 'K + L = M + N ile K + N > L + M toplanırsa 2K > 2M yani K > M bulunur. Eşitlikten K > M iken N > L olmak zorundadır. P < L verildiğinden P < L < N elde edilir; yani N kesinlikle P\'den ağırdır.'),
  ('Bir saatte akrep ile yelkovan saat 15.00\'ten sonra ilk kez saat 15\'i kaç dakika geçe üst üste gelir?', '180/11', ['165/11 dakika geçe', '195/11 dakika geçe', '15 dakika geçe'], '15.00\'te akrep 90° öndedir. Yelkovanın dakikadaki bağıl hızı 5,5° = 11/2°/dk olduğundan 90° farkı kapatması 90 / (11/2) = 180/11 dakika sürer.'),
  ('Bir şifre tablosunda 3×3\'lük karede 1. satırda K-L-M, 2. satırda N-O-P, 3. satırda R-S-T harfleri vardır. Her harf önce satır, sonra sütun numarasıyla iki basamaklı kodlanır (örneğin O = 22). Buna göre "332223" kodu hangi kelimeyi verir?', 'TOP', ['TOR kelimesidir', 'SOP kelimesidir', 'POP kelimesidir'], 'İkişerli gruplara ayrıldığında: 33 (3. satır 3. sütun = T), 22 (2. satır 2. sütun = O), 23 (2. satır 3. sütun = P). Şifrelenen kelime "TOP" olur.'),
  ('Bir güvenlik görevlisi 5 günde bir gece nöbeti tutmaktadır. İlk nöbetini Çarşamba günü tutan bu görevlinin 22. nöbeti hangi güne denk gelir?', 'Çarşamba', ['Perşembe gününe', 'Salı gününe', 'Cuma gününe'], '1. nöbetten 22. nöbete kadar 21 aralık vardır. Her aralık 5 gün olduğundan 21 × 5 = 105 gün geçer. 105 = 7 × 15 (kalan 0) olduğundan 22. nöbet yine Çarşamba günüdür.'),
  ('Bir kitap fuarında 1\'den 4\'e numaralı stantlarda Fizik, Kimya, Matematik ve Biyoloji yayınları vardır. Üç öğrenci şu tahminleri yapmıştır: 1. öğrenci "Fizik 1\'de, Kimya 2\'de", 2. öğrenci "Kimya 3\'te, Matematik 4\'te", 3. öğrenci "Biyoloji 1\'de, Matematik 2\'de". Her öğrencinin yalnızca bir tahmini doğru olduğu ve Fizik standının 1 numarada olmadığı biliniyorsa 3 numaralı stant hangisidir?', 'Fizik', ['Kimya standıdır', 'Biyoloji standıdır', 'Matematik standıdır'], 'Fizik≠1 olduğundan 1. öğrenciden Kimya=2 doğrudur. Kimya=2 olunca 2. öğrencide Kimya=3 yanlıştır, dolayısıyla Matematik=4 doğrudur. 3. öğrencide Matematik=2 yanlış olduğundan Biyoloji=1 doğrudur; boşta kalan 3 numaralı stant kesinlikle Fizik\'tir.'),
  ('Bir takvimde aynı yıl içinde 1 Temmuz ile 1 Ekim günleri arasındaki gün farkı kaçtır ve 1 Temmuz Salı ise 1 Ekim hangi güne denk gelir?', '92 gün, Çarşamba', ['91 gün, Salı', '92 gün, Perşembe', '90 gün, Pazartesi'], 'Temmuz 31, Ağustos 31, Eylül 30 gündür. Toplam gün farkı 31 + 31 + 30 = 92 gündür. 92\'nin 7 ile bölümünden kalan 1 (92 = 7×13 + 1) olduğundan Salı + 1 gün = Çarşamba olur.'),
  ('Bir kripto kuralında her harf 1-9 arası farklı bir rakamla kodlanmıştır. "SIRA" = 4261, "ARSA" = 1641 ve "SARI" = 4162 olduğuna göre "ASIR" kelimesinin kodu nedir?', '1426', ['1462 sayısıdır', '1624 sayısıdır', '4126 sayısıdır'], '"ARSA" = 1641 olduğundan A=1, R=6, S=4 bulunur. "SIRA" = 4261 olduğundan I=2 çıkar ("SARI" = 4162 doğrular). Böylece A(1)-S(4)-I(2)-R(6) = 1426 olur.'),
  ('Bir metro ağında M1 hattı 1-2-3-4-5, M2 hattı 6-2-7-8 ve M3 hattı 9-4-7-10 duraklarından oluşmaktadır. Her durak arası 4 dakika, her aktarma 3 dakikadır. 1 numaralı duraktan 10 numaralı durağa en kısa sürede gitmek isteyen yolcu hangi duraklarda aktarma yaparak kaç dakikada ulaşır?', '2 ve 7\'de aktarma, 18 dakika', ['Yalnızca 4\'te aktarma, 23 dakika', '2 ve 7\'de aktarma, 21 dakika', 'Yalnızca 4\'te aktarma, 19 dakika'], '4\'te tek aktarma: 1→2→3→4 (12 dk) + aktarma (3 dk) + 4→7→10 (8 dk) = 23 dk. 2 ve 7\'de çift aktarma: 1→2 (4 dk) + aktarma (3 dk) + 2→7 (4 dk) + aktarma (3 dk) + 7→10 (4 dk) = 18 dk. En kısa yol 2 ve 7 aktarmasıyla 18 dakikadır.'),
  ('Dört takımlı (A, B, C, D) tek devreli bir futbol turnuvasında (galibiyet 3, beraberlik 1, mağlubiyet 0) puanlar şöyledir: A=7, B=5, C=4. D takımının hiç beraberliği olmadığı bilindiğine göre D takımı kaç puan almıştır?', '0', ['3 puan almıştır', '1 puan almıştır', '2 puan almıştır'], 'A=7 (2G 1B 0M), B=5 (1G 2B 0M). İkisinin de 0M\'si olduğundan A ile B kesin berabere kalmıştır; B\'nin ikinci beraberliği C ile olmak zorundadır (D\'nin beraberliği yok!). O hâlde C=4 (1G 1B 1M): C, A\'ya yenilip B ile berabere kalmış ve D\'yi yenmiştir. Böylece D tüm maçlarını (A, B, C\'ye) kaybetmiş ve 0 puan almıştır.'),
  ('Üç farklı şehir (A, B, C) arasında tren seferleri vardır. A\'dan B\'ye her 15 dakikada bir, B\'den C\'ye her 20 dakikada bir tren kalkmaktadır. A-B arası yolculuk tam 32 dakika sürmektedir. Her iki istasyondan ilk trenler saat 09.00\'da kalktığına göre A\'dan saat 09.30\'da kalkan trene binen bir yolcu B\'de en az kaç dakika bekleyerek C trenine binebilir?', '18', ['12 dakika bekler', '8 dakika bekler', '15 dakika bekler'], '09.30\'da kalkan tren 32 dakika sonra saat 10.02\'de B\'ye ulaşır. B\'den C\'ye trenler 09.00, 09.20, 09.40, 10.00, 10.20 saatlerinde kalkmaktadır. 10.02\'de varan yolcu en erken 10.20 trenine biner ve 20 - 2 = 18 dakika bekler.'),
];
